from pathlib import Path
from datetime import datetime
from программы.расчёт_уз import рассчитать_уз
from программы.подбор_мер import подобрать_меры

def сформировать_документы(организация,системы,расчёты,подбор,оборудование,сзи,проблемы_оборудования,аудит):
 docs=Path('документы'); reports=Path('отчёты'); docs.mkdir(exist_ok=True); reports.mkdir(exist_ok=True); date=datetime.now().strftime('%d.%m.%Y %H:%M')
 (docs/'реестр_испдн.txt').write_text('РЕЕСТР ИСПДн\n'+ '\n'.join(f"№{s['номер']} {s['название']} | {s['категория_пдн']} | {s['тип_субъектов']} | {s['количество_субъектов']} | угрозы {s['тип_угроз_по_условию']} | ГИС: {s['является_гис']}" for s in системы),encoding='utf-8')
 акт=[]
 for s in системы:
  r=расчёты[s['номер']]; mismatch='РАСХОЖДЕНИЕ' if s.get('заявленный_уз') and s['заявленный_уз']!=r['уровень'] else 'нет'
  акт.append(f"АКТ определения уровня защищённости\nСистема: {s['номер']} — {s['название']}\nДата: {date}\nПараметры: категория={s['категория_пдн']}; субъект={s['тип_субъектов']}; количество={s['количество_субъектов']}; угрозы={s['тип_угроз_по_условию']}\nРассчитанный уровень: {r['уровень']}\nОбоснование: {r['обоснование']}\nЗаявленный ранее уровень: {s.get('заявленный_уз') or 'не задан'}\nРасхождение: {mismatch}\nУчебный расчёт, требуется нормативная проверка\n")
 (docs/'акты_определения_уз.txt').write_text('\n'.join(акт),encoding='utf-8')
 (docs/'перечень_оборудования.txt').write_text('ИНВЕНТАРИЗАЦИЯ\n'+ '\n'.join(f"{e['название']} | тип={e['тип']} | системы={e['связанная_испдн']} | ПДн={e['обрабатывает_пдн']} | место={e['размещение']} | класс={e['класс_по_учебной_схеме']} | роль={e['роль']}" for e in оборудование)+'\n\nПроблемы: '+str(проблемы_оборудования),encoding='utf-8')
 меры=[]
 for s in системы:
  p=подбор[s['номер']]
  меры.append(f"Система {s['номер']} {s['название']} — {расчёты[s['номер']]['уровень']}\nТребуется: {', '.join(m['код'] for m in p['требуемые_меры'])}\nФактически: {', '.join(p['фактические_меры'])}\nПробелы: {', '.join(x['код'] for x in p['пробелы'])}\n")
 (docs/'план_мер.txt').write_text('ПЛАН МЕР\n'+'\n'.join(меры),encoding='utf-8')
 (docs/'тз_на_сзпдн.txt').write_text(f"ТЕХНИЧЕСКОЕ ЗАДАНИЕ НА СЗПДн\nЦель: защита персональных данных в контурах организации {организация['название']}.\nСостав: идентификация, разграничение доступа, журналирование, резервное копирование, защита рабочих мест и сетевых каналов.\nЭтапы: 1) уточнение требований; 2) проектирование; 3) настройка; 4) испытания; 5) приёмка.\nОтветственный: {организация['ответственный_за_защиту_пдн']}.\nСрок: 30 календарных дней от утверждения.\nКритерии: меры внедрены, настройки проверены, тест восстановления успешен, документы оформлены.\nПодтверждения: протоколы настроек, журналы, акт испытаний, приказ и обучение.\n",encoding='utf-8')
 (docs/'план_исправлений.txt').write_text('ПЛАН ИСПРАВЛЕНИЙ\n'+'\n'.join(f"{i}. {g['код']} {g['название']} — {g['причина']}; действие: внедрить/подтвердить меру; приоритет: высокий; ответственный: ИБ; срок: 14 дней; зависимость: утверждение ТЗ; подтверждение: протокол; ожидаемый результат: пробел устранён." for i,(snum,p) in enumerate([(s['номер'],подбор[s['номер']]) for s in системы]) for g in p['пробелы'])+'\n'+ '\n'.join(f"Дополнительно: {x['оборудование']} — {', '.join(x['проблемы'])}; исправить инвентарную карточку в течение 7 дней." for x in проблемы_оборудования),encoding='utf-8')
 (docs/'минимизация_данных.txt').write_text('МИНИМИЗАЦИЯ ДАННЫХ\nДо: учебная аналитическая выгрузка {ФИО: «Иван Иванов», телефон: +7-000-000, адрес: условный, заявка: 104}.\nПосле: {код субъекта: C-104, регион: условный, заявка: типовое обслуживание}.\nИсключены прямые идентификаторы и детализация, не нужная аналитике. Риск повторной идентификации сохраняется при объединении с внешними сведениями; доступ и размер выборки следует ограничить. Удаление ФИО не меняет автоматически УЗ исходной ИСПДн.\n',encoding='utf-8')
 (reports/'отчёт_по_уровням.txt').write_text('РЕЗУЛЬТАТЫ РАСЧЁТА\n'+'\n'.join(f"{s['номер']} {s['название']}: {расчёты[s['номер']]['уровень']} — {расчёты[s['номер']]['обоснование']}" for s in системы)+'\nПорог: '+str(расчёты['пороговый_тест']),encoding='utf-8')
 (reports/'отчёт_по_мерам.txt').write_text('ПОДБОР МЕР\n'+'\n'.join(меры),encoding='utf-8')
 (reports/'отчёт_аудита.txt').write_text('АУДИТ\nОценка: '+str(аудит['оценка'])+'/100\n'+'\n'.join(f"{p['статус']} | {p['проверка']} | {p['исходный_факт']} | {p['рекомендация']}" for p in аудит['пункты'])+'\nДефекты: '+str(аудит['дефекты']),encoding='utf-8')
 (reports/'итоговый_отчёт.txt').write_text(f"ИТОГОВЫЙ УЧЕБНЫЙ ОТЧЁТ\nДата формирования: {date}\nОрганизация: {организация['название']} | {организация['отрасль']} | {организация['город']} | сотрудников {организация['число_сотрудников']}\nСистемы: {len(системы)}\n\n"+'\n'.join(f"Система {s['номер']}: {s['название']}; категория {s['категория_пдн']}; группа {s['тип_субъектов']}; субъектов {s['количество_субъектов']}; тип угроз {s['тип_угроз_по_условию']}; УЗ {расчёты[s['номер']]['уровень']}.\nОбоснование: {расчёты[s['номер']]['обоснование']}\nМеры требуются: {', '.join(m['код'] for m in подбор[s['номер']]['требуемые_меры'])}\nРеализованы: {', '.join(подбор[s['номер']]['фактические_меры'])}\nПробелы: {', '.join(g['код'] for g in подбор[s['номер']]['пробелы'])}" for s in системы)+f"\n\nОборудование: {len(оборудование)} записей. СЗИ/СКЗИ: {len(сзи)}.\nАудит: учебная оценка {аудит['оценка']}/100.\nДефекты: {аудит['дефекты']}\nПриоритетные действия: устранить пробелы мер; уточнить инвентаризацию; проверить классы и сертификаты средств; документировать применимость нормативов.\n\nНормативные источники для отдельной проверки: ФЗ №152-ФЗ; постановление Правительства РФ №1119; приказ ФСТЭК №21; приказ ФСТЭК №17 (применимость для ГИС). Редакции на дату выполнения следует сверить по официальным источникам.\nУчебная модель не является юридическим заключением или официальной оценкой регулятора.",encoding='utf-8')
